# -*- coding: utf-8 -*-
import json,html,math
src='.cowork-temp/highwin-kline-data.json';out='T0主板策略_高胜率形态_真实K线打印版.html'
charts=json.load(open(src,encoding='utf-8'))
D=json.dumps(charts,ensure_ascii=False,separators=(',',':'))
html_doc=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>T0主板策略｜高胜率形态真实K线打印版</title>
<style>
:root{{--ink:#15211b;--muted:#637269;--red:#d44242;--green:#168a5c;--gold:#b87a13;--paper:#fffdfa;--line:#cfd7cf}}*{{box-sizing:border-box}}body{{margin:0;background:#e9ece8;color:var(--ink);font-family:"Noto Serif CJK SC","Songti SC",STSong,serif}}.toolbar{{position:sticky;top:0;background:#15211b;color:#fff;padding:12px calc((100% - 1180px)/2);display:flex;justify-content:space-between;align-items:center;z-index:5;font:14px ui-monospace,Menlo,monospace}}button{{border:1px solid #88b7a4;background:#d9f1e5;color:#123123;padding:9px 16px;font-weight:700;cursor:pointer}}.wrap{{width:1180px;margin:22px auto;background:var(--paper);padding:52px 54px 64px;box-shadow:0 8px 30px #bac1bb}}.eyebrow{{font:700 11px ui-monospace,Menlo,monospace;letter-spacing:.16em;color:var(--green)}}h1{{font-size:40px;margin:11px 0 8px;letter-spacing:-.05em}}.lead{{font-size:15px;line-height:1.7;color:#425249;max-width:850px;border-left:3px solid var(--gold);padding-left:16px}}.legend{{display:flex;gap:20px;font-size:12px;color:var(--muted);margin:25px 0 12px;align-items:center}}.legend i{{display:inline-block;width:10px;height:10px;margin-right:5px}}.legend .up{{background:var(--red)}}.legend .down{{background:var(--green)}}.legend .box{{border:2px dashed var(--gold);background:transparent}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:22px 24px}}.card{{border:1px solid var(--line);break-inside:avoid;padding:15px 15px 12px;position:relative;background:#fff}}.head{{display:flex;justify-content:space-between;align-items:baseline;border-bottom:1px solid #e4e8e2;padding-bottom:9px;margin-bottom:6px}}.title{{font-size:17px;font-weight:700}}.sub{{font:11px ui-monospace,Menlo,monospace;color:var(--muted)}}.pnl{{font:700 16px ui-monospace,Menlo,monospace;color:var(--red)}}.chart{{width:100%;height:270px;display:block}}.caption{{margin:5px 0 0;font-size:12px;line-height:1.55;color:#536259}}.caption code{{font-family:ui-monospace,Menlo,monospace;background:#f0f3ef;padding:1px 4px;color:#294137}}.foot{{margin-top:30px;padding-top:13px;border-top:1px solid var(--line);font-size:11px;line-height:1.7;color:var(--muted)}}
@page{{size:A4 landscape;margin:9mm}}@media print{{body{{background:#fff}}.toolbar{{display:none}}.wrap{{width:auto;margin:0;padding:0;box-shadow:none}}h1{{font-size:28px}}.lead{{font-size:12px;margin:5px 0}}.grid{{gap:10px 12px}}.card{{padding:9px;break-inside:avoid}}.chart{{height:182px}}.title{{font-size:13px}}.sub,.caption,.legend,.foot{{font-size:8px}}.pnl{{font-size:12px}}.head{{padding-bottom:4px;margin-bottom:3px}}}}
</style></head><body><div class="toolbar"><span>GO-STOCK · 高胜率形态 · 实际 OHLC 等比例 K 线</span><button onclick="window.print()">打印 / 导出 PDF</button></div><main class="wrap"><div class="eyebrow">MAINBOARD T0 / ACTUAL OHLC / 15 CHARTS</div><h1>高胜率形态 · 真实 K 线逐笔打印</h1><p class="lead">每张图基于对应交易日的本地日线缓存绘制。蜡烛实体、上下影线、价格位置均按实际 OHLC 等比例呈现；金色虚框标出 3K 形态，最后一根为 T0 当日。红实体＝收涨，绿实体＝收跌。</p><div class="legend"><span><i class="up"></i>收涨实体</span><span><i class="down"></i>收跌实体</span><span><i class="box"></i>3K 形态窗口</span><span>浮盈＝收盘涨幅－开盘涨幅（开盘买入、收盘卖出）</span></div><section id="charts" class="grid"></section><p class="foot">筛选范围：项目主板 T0 策略的 398 个交易日历史缓存（2025-01-02～2026-08-22）。仅展示历史“达标率 &gt;70% 且 T0 样本 ≥5”的两个 3K 形态：<code>DYIN|YX|MYIN</code>（8 笔）与 <code>ZT|DYIN|DT</code>（7 笔）。注意：这些是同一历史样本内筛选结果，且均未达系统 N≥10 的生产样本门槛。</p></main><script>const DATA={D};const esc=s=>String(s).replace(/[&<>]/g,m=>({{'&':'&amp;','<':'&lt;','>':'&gt;'}}[m]));function chart(c){{let b=c.bars,w=520,h=270,p={{l:45,r:13,t:19,b:35}},cw=w-p.l-p.r,ch=h-p.t-p.b;let lo=Math.min(...b.map(x=>x.low)),hi=Math.max(...b.map(x=>x.high)),pad=(hi-lo)*.075||1;lo-=pad;hi+=pad;const Y=v=>p.t+(hi-v)/(hi-lo)*ch;const X=i=>p.l+cw*(i+.5)/b.length;let step=cw/b.length,body=Math.min(28,step*.58),s='';let ticks=[];for(let i=0;i<5;i++)ticks.push(lo+(hi-lo)*i/4);ticks.forEach(v=>{{let y=Y(v);s+=`<line x1="${{p.l}}" y1="${{y}}" x2="${{w-p.r}}" y2="${{y}}" stroke="#e4e9e4"/><text x="${{p.l-5}}" y="${{y+3.5}}" text-anchor="end" fill="#637269" font-family="ui-monospace,Menlo,monospace" font-size="9">${{v.toFixed(2)}}</text>`}});let fi=b.length-4;let x0=X(fi)-step*.48,x1=X(b.length-1)+step*.48;s+=`<rect x="${{x0}}" y="${{p.t}}" width="${{x1-x0}}" height="${{ch}}" fill="#fdf8e9" stroke="#b87a13" stroke-width="1.4" stroke-dasharray="4 3"/><text x="${{x0+4}}" y="${{p.t+12}}" fill="#9e6810" font-family="ui-monospace,Menlo,monospace" font-size="9">3K 形态 → T0日</text>`;b.forEach((x,i)=>{{let xx=X(i),up=x.close>=x.open,col=up?'#d44242':'#168a5c',yt=Y(Math.max(x.open,x.close)),yb=Y(Math.min(x.open,x.close)),bh=Math.max(1,yb-yt);s+=`<line x1="${{xx}}" y1="${{Y(x.high)}}" x2="${{xx}}" y2="${{Y(x.low)}}" stroke="${{col}}" stroke-width="1.25"/><rect x="${{xx-body/2}}" y="${{yt}}" width="${{body}}" height="${{bh}}" fill="${{col}}"/>`;if(i===0||i===fi||i===b.length-1)s+=`<text x="${{xx}}" y="${{h-12}}" text-anchor="middle" fill="#637269" font-family="ui-monospace,Menlo,monospace" font-size="8">${{x.date.slice(5)}}</text>`}});s+=`<text x="${{w-p.r}}" y="${{h-12}}" text-anchor="end" fill="#9e6810" font-family="ui-monospace,Menlo,monospace" font-size="9">T0</text>`;return `<svg class="chart" viewBox="0 0 ${{w}} ${{h}}" aria-label="${{c.name}} ${{c.date}} 实际K线">${{s}}</svg>`}}document.querySelector('#charts').innerHTML=DATA.map(c=>`<article class="card"><div class="head"><div><div class="title">${{esc(c.name)}} <span class="sub">${{esc(c.code)}} · ${{c.date}}</span></div><div class="sub">${{esc(c.pattern)}} · 末 3 根为形态，最后一根为 T0 当日</div></div><div class="pnl">+${{c.pnl.toFixed(2)}}%</div></div>${{chart(c)}}<p class="caption">实际 OHLC 比例绘制 · T0 日：<code>${{c.bars[c.bars.length-1].date}}</code> · 图中显示 T0 前 9 个交易日 + 当日</p></article>`).join('');</script></body></html>'''
open(out,'w',encoding='utf-8').write(html_doc);print(out)
